##
##  # ---------- Calibration anchors ----------
##  # Cyclosporine 0.05% BID (Sall 2000; ATP III) : Schirmer +>=10mm responder ~15%
##  #   vs ~5% vehicle at 6mo; CFS improvement by mo 3-6 (slow onset, modeled via
##  #   low KOUT_AQP/KOUT_NERVE).
##  # Cyclosporine 0.09% (Cequa, Tauber 2018)     : Schirmer responder ~17% at wk12,
##  #   higher aqueous concentration -> larger EC50_CSA occupancy vs 0.05%.
##  # Lifitegrast (OPUS-2/3)                      : CFS -0.9 to -1.1 vs vehicle at
##  #   wk6 (faster onset than CsA, modeled via higher KOUT_LIF / faster DC effect).
##  # Loteprednol 0.25% QID (short pulse)          : OSDI/CFS improvement within
##  #   2wk (fastest onset); IOP elevation risk tracked via LOT_AUC (do not use
##  #   >2-4wk continuously in practice).
##  # Perfluorohexyloctane (GOBI/MOJAVE)           : TSS -7 to -10 vs saline, CFS
##  #   -0.5 to -0.9 at wk8; acts purely via evaporation-barrier (Pfho_eff on
##  #   EvapRate), no direct anti-inflammatory arm.
##  # Varenicline nasal spray (ONSET-1/2)          : Schirmer +~4-5mm at wk4 vs
##  #   placebo spray; acts via trigeminal reflex (Var_eff on AQP/MUCIN), not
##  #   anti-inflammatory.
##  # Diquafosol 3% (Japan/Korea trials)           : TBUT +~1.5-2s, fluorescein
##  #   staining -1 to -2 at wk2-4; acts via P2Y2 mucin+aqueous secretagogue.
##  # TFOS DEWS II vicious-cycle framework          : hyperosmolarity <-> innate/
##  #   adaptive inflammation <-> epithelial damage feed-forward loop reproduced
##  #   via OSM_target's dependence on chronic_immune_norm and MUCIN.
##
##  # ---------- Quick sanity plots ----------
##  # df <- DED_simulate_scenarios(84)
##  # ggplot(df, aes(time, OSDI_score, colour=scenario)) + geom_line()
##  # ggplot(df, aes(time, TBUT_s, colour=scenario)) + geom_line()
##  # ggplot(df, aes(time, Corneal_staining, colour=scenario)) + geom_line()
##  # ggplot(df, aes(time, Schirmer_mm, colour=scenario)) + geom_line()
